using Microsoft.VisualStudio.TestTools.UnitTesting;
using Commerce;

namespace Commerce.Tests;

[TestClass]
public class ShoppingCartTests
{
    private ShoppingCart _cart = null!;

    [TestInitialize]
    public void Setup() => _cart = new ShoppingCart();

    // --- AddItem ---

    [TestMethod]
    public void AddItem_SingleItem_IncreasesTotal()
    {
        _cart.AddItem("SKU-1", 9.99m, 2);

        Assert.AreEqual(19.98m, _cart.GetTotal());
    }

    [TestMethod]
    public void AddItem_MultipleItems_SumsCorrectly()
    {
        _cart.AddItem("A", 5.00m, 1);
        _cart.AddItem("B", 3.50m, 4);

        Assert.AreEqual(19.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void AddItem_ZeroQuantity_ContributesNothing()
    {
        _cart.AddItem("A", 10.00m, 0);

        Assert.AreEqual(0m, _cart.GetTotal());
    }

    // --- RemoveItem ---

    [TestMethod]
    public void RemoveItem_ExistingItem_ReturnsTrue()
    {
        _cart.AddItem("X", 1.00m, 1);

        Assert.IsTrue(_cart.RemoveItem("X"));
    }

    [TestMethod]
    public void RemoveItem_ExistingItem_ReducesTotal()
    {
        _cart.AddItem("X", 5.00m, 2);
        _cart.AddItem("Y", 3.00m, 1);

        _cart.RemoveItem("X");

        Assert.AreEqual(3.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void RemoveItem_NonExistentItem_ReturnsFalse()
    {
        _cart.AddItem("X", 1.00m, 1);

        Assert.IsFalse(_cart.RemoveItem("Z"));
    }

    [TestMethod]
    public void RemoveItem_DuplicateSkus_RemovesAll()
    {
        _cart.AddItem("X", 1.00m, 1);
        _cart.AddItem("X", 2.00m, 1);

        _cart.RemoveItem("X");

        Assert.AreEqual(0m, _cart.GetTotal());
    }

    // --- GetTotal ---

    [TestMethod]
    public void GetTotal_EmptyCart_ReturnsZero()
    {
        Assert.AreEqual(0m, _cart.GetTotal());
    }

    [TestMethod]
    public void GetTotal_AfterRemovingAllItems_ReturnsZero()
    {
        _cart.AddItem("A", 7.00m, 3);
        _cart.RemoveItem("A");

        Assert.AreEqual(0m, _cart.GetTotal());
    }

    // --- ApplyPromoCode (future implementation) ---
    // Uncomment these once ApplyPromoCode is added to ShoppingCart.

    // [TestMethod]
    // public void ApplyPromoCode_ValidCode_ReducesTotal()
    // {
    //     _cart.AddItem("A", 100.00m, 1);
    //     _cart.ApplyPromoCode("SAVE10"); // 10% off
    //
    //     Assert.AreEqual(90.00m, _cart.GetTotal());
    // }

    // [TestMethod]
    // public void ApplyPromoCode_InvalidCode_TotalUnchanged()
    // {
    //     _cart.AddItem("A", 50.00m, 1);
    //     _cart.ApplyPromoCode("BOGUS");
    //
    //     Assert.AreEqual(50.00m, _cart.GetTotal());
    // }

    // [TestMethod]
    // public void ApplyPromoCode_EmptyCart_TotalRemainsZero()
    // {
    //     _cart.ApplyPromoCode("SAVE10");
    //
    //     Assert.AreEqual(0m, _cart.GetTotal());
    // }
}

